import { NextResponse, type NextRequest } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

// Optimistic check only: bounces visitors with no session cookie before rendering.
// The dashboard itself still validates the session (see requireUser in lib/users).
export function proxy(request: NextRequest) {
  if (!getSessionCookie(request)) {
    const url = new URL("/sign-in", request.url);
    url.searchParams.set("next", request.nextUrl.pathname);
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*"],
};
EOF
cat > src/lib/users.ts <<'EOF'
import "server-only";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { auth } from "./auth";
import { db } from "./db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = { id: string; email: string; name: string; createdAt: string | number };

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: new Date(row.createdAt).toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt')
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?')
    .get(id) as UserRow | undefined;
  return row && toUser(row);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return undefined;
  const { id, email, name, createdAt } = session.user;
  return toUser({ id, email, name, createdAt: createdAt.toISOString() });
}

export async function requireUser(next = "/dashboard"): Promise<User> {
  const user = await getCurrentUser();
  if (!user) redirect(`/sign-in?next=${encodeURIComponent(next)}`);
  return user;
}
EOF
