"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

// Only allow same-site relative paths so ?next= can't be used as an open redirect.
function safeNext(value: string | null): string {
  return value && value.startsWith("/") && !value.startsWith("//") ? value : "/dashboard";
}

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const next = safeNext(useSearchParams().get("next"));
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    setPending(true);
    setError(null);
    const { error } = isSignUp
      ? await authClient.signUp.email({ email, password, name: String(form.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);

    if (error) {
      setError(error.message ?? "Something went wrong");
      return;
    }
    router.push(next);
    router.refresh();
  }

  async function onGoogle() {
    setError(null);
    const { error } = await authClient.signIn.social({ provider: "google", callbackURL: next });
    if (error) setError(error.message ?? "Google sign-in failed");
  }

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your account" : "Sign in to Notely"}</h1>

      <form onSubmit={onSubmit} className="mt-6 flex flex-col gap-3">
        {isSignUp && (
          <input name="name" required placeholder="Name" autoComplete="name" className="rounded border px-3 py-2" />
        )}
        <input name="email" type="email" required placeholder="Email" autoComplete="email" className="rounded border px-3 py-2" />
        <input
          name="password"
          type="password"
          required
          minLength={8}
          placeholder="Password"
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className="rounded border px-3 py-2"
        />
        <button type="submit" disabled={pending} className="rounded bg-foreground px-3 py-2 text-background disabled:opacity-50">
          {pending ? "…" : isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>

      <button onClick={onGoogle} className="mt-3 w-full rounded border px-3 py-2">
        Continue with Google
      </button>

      {error && <p className="mt-3 text-sm text-red-600">{error}</p>}

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? "Already have an account? " : "New to Notely? "}
        <Link href={`/${isSignUp ? "sign-in" : "sign-up"}?next=${encodeURIComponent(next)}`} className="underline">
          {isSignUp ? "Sign in" : "Sign up"}
        </Link>
      </p>
    </main>
  );
}
